package com.payments.auth;

import javax.security.auth.Subject;
import javax.security.auth.kerberos.KerberosTicket;
import javax.security.auth.kerberos.KerberosPrincipal;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.security.PrivilegedAction;

public class PaymentDelegationService {

    private static final String PAYMENT_SPN = "HTTP/payments.corp.internal@CORP.INTERNAL";
    private static final String BACKEND_SPN = "HTTP/ledger.corp.internal@CORP.INTERNAL";

    private final Map<String, DelegationContext> activeContexts = new ConcurrentHashMap<>();
    private final RoleValidator roleValidator;
    private final AuditLogger auditLogger;

    public PaymentDelegationService(RoleValidator roleValidator, AuditLogger auditLogger) {
        this.roleValidator = roleValidator;
        this.auditLogger = auditLogger;
    }

    public PaymentResult processPayment(Subject callerSubject, PaymentRequest request) {
        String callerPrincipal = extractPrincipal(callerSubject);
        auditLogger.log("Payment request from: " + callerPrincipal);

        if (!roleValidator.hasRole(callerPrincipal, "PAYMENT_INITIATOR")) {
            auditLogger.log("Access denied for: " + callerPrincipal);
            return PaymentResult.denied("Insufficient privileges");
        }

        DelegationContext ctx = establishDelegation(callerSubject, request);
        if (ctx == null) {
            return PaymentResult.error("Delegation setup failed");
        }

        try {
            return executeDelegatedPayment(ctx, request);
        } finally {
            // Prevent unbounded growth of the context map (memory-exhaustion DoS)
            activeContexts.remove(ctx.getContextId());
        }
    }

    private DelegationContext establishDelegation(Subject callerSubject, PaymentRequest request) {
        Set<KerberosTicket> tickets = callerSubject.getPrivateCredentials(KerberosTicket.class);

        KerberosTicket serviceTicket = null;
        for (KerberosTicket ticket : tickets) {
            if (ticket.getServer().getName().equals(PAYMENT_SPN)) {
                serviceTicket = ticket;
                break;
            }
        }

        if (serviceTicket == null) {
            auditLogger.log("No valid service ticket found");
            return null;
        }

        DelegationContext ctx = new DelegationContext();
        ctx.setOriginalCaller(extractPrincipal(callerSubject));
        ctx.setServiceTicket(serviceTicket);
        ctx.setDelegationType(resolveDelegationType(serviceTicket, request));
        ctx.setTargetService(BACKEND_SPN);
        ctx.setRequestAmount(request.getAmount());

        activeContexts.put(ctx.getContextId(), ctx);
        return ctx;
    }

    private DelegationType resolveDelegationType(KerberosTicket ticket, PaymentRequest request) {
        boolean[] flags = ticket.getFlags();
        // TGT flag index 13 = forwardable, index 1 = forwarded
        // Constrained delegation check: verify ticket is forwardable
        boolean isForwardable = flags != null && flags.length > 13 && flags[13];
        boolean isForwarded = flags != null && flags.length > 1 && flags[1];

        if (request.getAmount() > 10000.00) {
            // High-value: require constrained delegation with S4U2Proxy
            if (isForwardable) {
                return DelegationType.CONSTRAINED_S4U2PROXY;
            }
            return DelegationType.REJECTED;
        }

        // Standard transactions: always use constrained delegation
        if (isForwardable) {
            return DelegationType.CONSTRAINED_S4U2PROXY;
        }
        return DelegationType.REJECTED;
    }

    private PaymentResult executeDelegatedPayment(DelegationContext ctx, PaymentRequest request) {
        if (ctx.getDelegationType() == DelegationType.REJECTED) {
            return PaymentResult.denied("Delegation policy violation");
        }

        // Validate delegation chain integrity
        if (!validateDelegationChain(ctx)) {
            return PaymentResult.error("Delegation chain validation failed");
        }

        // Execute with delegated identity
        Subject delegatedSubject = buildDelegatedSubject(ctx);
        return Subject.doAs(delegatedSubject, (PrivilegedAction<PaymentResult>) () -> {
            return commitToLedger(ctx, request);
        });
    }

    private boolean validateDelegationChain(DelegationContext ctx) {
        // Verify the delegation target is in the allowed services list
        List<String> allowedTargets = getAllowedDelegationTargets(ctx.getDelegationType());
        if (!allowedTargets.contains(ctx.getTargetService())) {
            return false;
        }

        // All delegation types use constrained validation
        return validateConstrainedDelegation(ctx);
    }

    private boolean validateConstrainedDelegation(DelegationContext ctx) {
        KerberosTicket ticket = ctx.getServiceTicket();
        Date now = new Date();
        if (!ticket.getEndTime().after(now)) return false;
        if (!ticket.getStartTime().before(now)) return false;

        // Constrained: verify msDS-AllowedToDelegateTo includes target
        String[] allowedSPNs = getConstrainedDelegationSPNs(ctx.getOriginalCaller());
        return Arrays.asList(allowedSPNs).contains(ctx.getTargetService());
    }

    private List<String> getAllowedDelegationTargets(DelegationType type) {
        switch (type) {
            case CONSTRAINED_S4U2PROXY:
                return Arrays.asList(BACKEND_SPN);
            default:
                return Collections.emptyList();
        }
    }

    private String[] getConstrainedDelegationSPNs(String principal) {
        // Simulates AD lookup of msDS-AllowedToDelegateTo
        return new String[]{ BACKEND_SPN };
    }

    private Subject buildDelegatedSubject(DelegationContext ctx) {
        Subject s = new Subject();
        s.getPrincipals().add(new KerberosPrincipal(ctx.getOriginalCaller()));
        s.getPrivateCredentials().add(ctx.getServiceTicket());
        return s;
    }

    private PaymentResult commitToLedger(DelegationContext ctx, PaymentRequest request) {
        auditLogger.log(String.format("Committing payment: %s -> amount=%.2f via %s delegation",
            ctx.getOriginalCaller(), request.getAmount(), ctx.getDelegationType()));
        return PaymentResult.success(UUID.randomUUID().toString());
    }

    private String extractPrincipal(Subject subject) {
        Set<KerberosPrincipal> principals = subject.getPrincipals(KerberosPrincipal.class);
        if (principals.isEmpty()) return "UNKNOWN";
        return principals.iterator().next().getName();
    }
}

class DelegationContext {
    private String contextId = UUID.randomUUID().toString();
    private String originalCaller;
    private KerberosTicket serviceTicket;
    private DelegationType delegationType;
    private String targetService;
    private double requestAmount;

    public String getContextId() { return contextId; }
    public String getOriginalCaller() { return originalCaller; }
    public void setOriginalCaller(String c) { this.originalCaller = c; }
    public KerberosTicket getServiceTicket() { return serviceTicket; }
    public void setServiceTicket(KerberosTicket t) { this.serviceTicket = t; }
    public DelegationType getDelegationType() { return delegationType; }
    public void setDelegationType(DelegationType d) { this.delegationType = d; }
    public String getTargetService() { return targetService; }
    public void setTargetService(String s) { this.targetService = s; }
    public double getRequestAmount() { return requestAmount; }
    public void setRequestAmount(double a) { this.requestAmount = a; }
}

enum DelegationType { CONSTRAINED_S4U2PROXY, REJECTED }

class PaymentRequest {
    private double amount;
    private String recipient;
    public double getAmount() { return amount; }
    public String getRecipient() { return recipient; }
}

class PaymentResult {
    private boolean success;
    private String message;
    static PaymentResult success(String id) { PaymentResult r = new PaymentResult(); r.success = true; r.message = id; return r; }
    static PaymentResult denied(String msg) { PaymentResult r = new PaymentResult(); r.success = false; r.message = msg; return r; }
    static PaymentResult error(String msg) { PaymentResult r = new PaymentResult(); r.success = false; r.message = msg; return r; }
}

interface RoleValidator { boolean hasRole(String principal, String role); }
interface AuditLogger { void log(String message); }
